import subprocess,json
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
print('ROOT KEYS',list(r))
print('CONTEXT KEYS',list(r.get('context',{})))
for k,v in r.items():
 if k not in ['context','study_schema']: print(k,json.dumps(v))
c=r.get('context',{})
for k,v in c.items():
 if k not in ['history','knowledge']: print('CONTEXT',k,json.dumps(v)[:18000])
print('HISTORY')
for h in c.get('history',[]):
 print(json.dumps({k:v for k,v in h.items() if k"'!='"'validation'}))
 print('validation',json.dumps({k:v for k,v in h.get('validation',{}).items() if k"'!='"'slices'}))
PY"

